def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    my_last, opp_last = history[-1]
    prev_my = history[-2][0]

    opp_d = 0
    my_d = 0
    for m, o in history:
        if o == 'D':
            opp_d += 1
        if m == 'D':
            my_d += 1

    if opp_d == n:
        return 'D'

    unprov = 0
    my_c_trans = 0
    d_trans = 0
    d_to_c = 0
    recent_opp_d = 0
    recent_unprov = 0
    recent_my_c = 0
    recent_start = max(1, n - 24)

    for i in range(1, n):
        pm = history[i - 1][0]
        co = history[i][1]

        if pm == 'C':
            my_c_trans += 1
            if co == 'D':
                unprov += 1
        else:
            d_trans += 1
            if co == 'C':
                d_to_c += 1

        if i >= recent_start:
            if co == 'D':
                recent_opp_d += 1
            if pm == 'C':
                recent_my_c += 1
                if co == 'D':
                    recent_unprov += 1

    hostile = False
    if n > 8:
        if opp_d * 5 >= 4 * n:
            hostile = True
        if my_c_trans >= 6 and unprov * 2 >= my_c_trans:
            hostile = True
        if recent_my_c >= 8 and recent_unprov >= 4:
            hostile = True
        if recent_opp_d >= 22 and recent_my_c >= 8 and recent_unprov >= 2:
            hostile = True

    if hostile:
        if opp_last == 'D' and prev_my == 'D' and unprov == 0 and d_to_c > 0:
            return 'C'
        return 'D'

    if opp_last == 'D':
        if prev_my == 'C':
            return 'D'

        streak = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                streak += 1
            else:
                break

        if streak <= 3:
            return 'C'

        if recent_unprov == 0 and opp_d * 5 <= 2 * n:
            if rng.random() < 0.2:
                return 'C'

        return 'D'

    if d_to_c > 0 and d_to_c * 2 > d_trans and unprov == 0 and opp_d == 0:
        if my_last == 'C':
            return 'D'
        return 'D' if rng.random() < 0.9 else 'C'

    if opp_d == 0 and my_d == 0 and n >= 60:
        if rng.random() < 0.015:
            return 'D'

    return 'C'
